import sys


def main():
    input_line = sys.stdin.buffer.readline
    n = int(input_line())
    stack = []
    required = 1
    reorders = 0

    for _ in range(2 * n):
        command = input_line().split()
        if command[0] == b"add":
            stack.append(int(command[1]))
        else:
            if stack:
                if stack[-1] == required:
                    stack.pop()
                else:
                    reorders += 1
                    stack.clear()
            required += 1

    print(reorders)


if __name__ == "__main__":
    main()
